/// Files here are generated by the test itself — a gradient, a hand-written PDF, a one-second
/// solid-colour clip — and live in a temporary directory shaped like WhatsApp's `Message/`.
private struct MediaFixture {
    let directory: URL
    var root: URL { directory.appendingPathComponent("Message") }
    var media: URL { root.appendingPathComponent("Media") }
    var outside: URL { directory.appendingPathComponent("outside") }

    init() throws {
        directory = FileManager.default.temporaryDirectory
            .appendingPathComponent("whatsapp-media-\(UUID().uuidString)")
        try FileManager.default.createDirectory(at: media, withIntermediateDirectories: true)
        try FileManager.default.createDirectory(at: outside, withIntermediateDirectories: true)
    }

    func remove() { try? FileManager.default.removeItem(at: directory) }

    func store(_ messages: [(id: Int64, body: MessageBody, text: String?)]) -> FakeWhatsAppStore {
        let store = FakeWhatsAppStore()
        store.messagesValue = messages.map {
            Fixtures.message(id: $0.id, chatID: 1, chatName: "Ane", text: $0.text, body: $0.body)
        }
        return store
    }

    func tools(_ store: FakeWhatsAppStore) -> WhatsAppTools {
        WhatsAppTools(store: store, mediaFiles: MediaFiles(root: root), calendar: Fixtures.calendar)
    }

    func file(_ name: String, _ data: Data) throws -> String {
        let url = media.appendingPathComponent(name)
        try data.write(to: url)
        return url.path
    }
}

private func contents(
    _ tools: WhatsAppTools, _ name: String, _ arguments: [String: Value]
) async -> (content: [Tool.Content], isError: Bool) {
    let result = await tools.handle(.init(name: name, arguments: arguments))
    return (result.content, result.isError ?? false)
}

private func texts(_ content: [Tool.Content]) -> String {
    content.compactMap { if case .text(let text, _, _) = $0 { text } else { nil } }
        .joined(separator: "\n")
}

private func images(_ content: [Tool.Content]) -> [(data: Data, mime: String)] {
    content.compactMap {
        if case .image(let base64, let mime, _, _) = $0, let data = Data(base64Encoded: base64) {
            (data, mime)
        } else { nil }
    }
}

/// A PNG with a transparent corner, wider than the viewing limit.
private func makePNG(width: Int, height: Int) throws -> Data {
    let context = try #require(
        CGContext(
            data: nil, width: width, height: height, bitsPerComponent: 8, bytesPerRow: 0,
            space: CGColorSpaceCreateDeviceRGB(),
            bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue))
    context.setFillColor(CGColor(red: 0.8, green: 0.1, blue: 0.1, alpha: 1))
    context.fill(CGRect(x: 0, y: 0, width: width / 2, height: height))
    let output = NSMutableData()
    let destination = try #require(
        CGImageDestinationCreateWithData(output, UTType.png.identifier as CFString, 1, nil))
    CGImageDestinationAddImage(destination, try #require(context.makeImage()), nil)
    #expect(CGImageDestinationFinalize(destination))
    return output as Data
}

/// A minimal one-page PDF. PDFKit rebuilds a cross-reference table it does not like, so the
/// offsets do not have to be exact.
/// A PNG whose header claims far more pixels than its few bytes could ever hold: all an
/// image-bomb check needs, since the dimensions are read before any pixel is.
private func makeBombHeader(width: UInt32, height: UInt32) -> Data {
    func crc(_ bytes: [UInt8]) -> UInt32 {
        var value: UInt32 = 0xFFFF_FFFF
        for byte in bytes {
            value ^= UInt32(byte)
            for _ in 0..<8 { value = (value & 1) != 0 ? (value >> 1) ^ 0xEDB8_8320 : value >> 1 }
        }
        return ~value
    }
    func big(_ value: UInt32) -> [UInt8] {
        [UInt8(value >> 24), UInt8((value >> 16) & 255), UInt8((value >> 8) & 255), UInt8(value & 255)]
    }
    let type = Array("IHDR".utf8)
    let body = big(width) + big(height) + [8, 0, 0, 0, 1]  // 8-bit grey, interlaced
    var data = Data([0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A])
    data.append(contentsOf: big(UInt32(body.count)) + type + body + big(crc(type + body)))
    return data
}

private func makePDF(text: String?, pages: Int = 1) -> Data {
    if pages > 1 {
        let kids = (0..<pages).map { "\(10 + $0) 0 R" }.joined(separator: " ")
        var parts = [
            "%PDF-1.4", "1 0 obj << /Type /Catalog /Pages 2 0 R >> endobj",
            "2 0 obj << /Type /Pages /Kids [\(kids)] /Count \(pages) >> endobj",
            "5 0 obj << /Type /Font /Subtype /Type1 /BaseFont /Helvetica >> endobj",
        ]
        for index in 0..<pages {
            let stream = "BT /F1 24 Tf 50 700 Td (Page \(index + 1) text) Tj ET"
            parts.append(
                "\(10 + index) 0 obj << /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Contents \(100 + index) 0 R /Resources << /Font << /F1 5 0 R >> >> >> endobj")
            parts.append(
                "\(100 + index) 0 obj << /Length \(stream.count) >> stream\n\(stream)\nendstream endobj")
        }
        parts.append("trailer << /Root 1 0 R /Size 200 >>\n%%EOF")
        return Data(parts.joined(separator: "\n").utf8)
    }
    let stream = text.map { "BT /F1 24 Tf 50 700 Td (\($0)) Tj ET" } ?? ""
    return Data(
        """
        %PDF-1.4
        1 0 obj << /Type /Catalog /Pages 2 0 R >> endobj
        2 0 obj << /Type /Pages /Kids [3 0 R] /Count 1 >> endobj
        3 0 obj << /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Contents 4 0 R /Resources << /Font << /F1 5 0 R >> >> >> endobj
        4 0 obj << /Length \(stream.count) >> stream
        \(stream)
        endstream endobj
        5 0 obj << /Type /Font /Subtype /Type1 /BaseFont /Helvetica >> endobj
        trailer << /Root 1 0 R /Size 6 >>
        %%EOF
        """.utf8)
}

private func makeVideo(at url: URL) async throws {
    let writer = try AVAssetWriter(outputURL: url, fileType: .mp4)
    let input = AVAssetWriterInput(
        mediaType: .video,
        outputSettings: [
            AVVideoCodecKey: AVVideoCodecType.h264, AVVideoWidthKey: 160, AVVideoHeightKey: 120,
        ])
    let adaptor = AVAssetWriterInputPixelBufferAdaptor(
        assetWriterInput: input,
        sourcePixelBufferAttributes: [
            kCVPixelBufferPixelFormatTypeKey as String: kCVPixelFormatType_32BGRA,
            kCVPixelBufferWidthKey as String: 160, kCVPixelBufferHeightKey as String: 120,
        ])
    writer.add(input)
    writer.startWriting()
    writer.startSession(atSourceTime: .zero)
    for frame in 0..<30 {
        while !input.isReadyForMoreMediaData { try await Task.sleep(nanoseconds: 1_000_000) }
        var buffer: CVPixelBuffer?
        CVPixelBufferCreate(nil, 160, 120, kCVPixelFormatType_32BGRA, nil, &buffer)
        let pixels = try #require(buffer)
        CVPixelBufferLockBaseAddress(pixels, [])
        memset(CVPixelBufferGetBaseAddress(pixels), Int32(frame * 8), CVPixelBufferGetDataSize(pixels))
        CVPixelBufferUnlockBaseAddress(pixels, [])
        adaptor.append(pixels, withPresentationTime: CMTime(value: Int64(frame), timescale: 30))
    }
    input.markAsFinished()
    await writer.finishWriting()
    #expect(writer.status == .completed)
}

@Suite("Attachment files")
struct MediaToolsTests {

    @Test("media_get reports the real path, type, size and a SHA-256 that matches")
    func mediaGetReportsFacts() async throws {
        let fixture = try MediaFixture()
        defer { fixture.remove() }
        let bytes = try makePNG(width: 64, height: 32)
        let path = try fixture.file("photo.png", bytes)
        let store = fixture.store([(10, Fixtures.attachment(.photo, path: path), "an invented caption")])

        let (content, isError) = await contents(
            fixture.tools(store), ToolCatalog.mediaGetName, ["message_id": .int(10)])
        let text = texts(content)
        #expect(!isError, Comment(rawValue: text))
        let expected = SHA256.hash(data: bytes).map { String(format: "%02x", $0) }.joined()
        #expect(text.contains("sha256: \(expected)"))
        #expect(text.contains("type: image/png"))
        #expect(text.contains("size: \(bytes.count) bytes"))
        #expect(text.contains("caption: an invented caption"))
        #expect(text.contains(URL(fileURLWithPath: path).resolvingSymlinksInPath().path))
    }

    @Test("An evicted file is reported as not on this Mac, not as an error")
    func missingFileIsSaid() async throws {
        let fixture = try MediaFixture()
        defer { fixture.remove() }
        let store = fixture.store([(10, Fixtures.attachment(.photo, path: nil), nil)])
        for tool in [ToolCatalog.mediaGetName, ToolCatalog.mediaViewName] {
            let (content, isError) = await contents(
                fixture.tools(store), tool, ["message_id": .int(10)])
            #expect(!isError)
            #expect(texts(content).contains("not on this Mac"))
            #expect(images(content).isEmpty)
        }
    }

    @Test("A path outside Message/ is refused, however it gets there")
    func pathsOutsideTheRootAreRefused() async throws {
        let fixture = try MediaFixture()
        defer { fixture.remove() }
        let secret = fixture.outside.appendingPathComponent("secret.png")
        try makePNG(width: 8, height: 8).write(to: secret)
        let link = fixture.media.appendingPathComponent("linked.png")
        try FileManager.default.createSymbolicLink(at: link, withDestinationURL: secret)

        for path in [
            secret.path,  // plainly elsewhere
            fixture.media.path + "/../../outside/secret.png",  // traversal
            link.path,  // a link inside the root that leads out
            "/etc/hosts",
        ] {
            let store = fixture.store([(10, Fixtures.attachment(.photo, path: path), nil)])
            for tool in [ToolCatalog.mediaGetName, ToolCatalog.mediaViewName] {
                let (content, isError) = await contents(
                    fixture.tools(store), tool, ["message_id": .int(10)])
                #expect(isError, "\(tool) opened \(path)")
                #expect(images(content).isEmpty, "\(tool) returned an image for \(path)")
                #expect(texts(content).contains("not inside WhatsApp's Message folder"))
            }
        }
    }

    @Test("A message with no attachment is refused with an explanation")
    func textMessageHasNoFile() async throws {
        let fixture = try MediaFixture()
        defer { fixture.remove() }
        let store = fixture.store([(10, .text, "hello")])
        let (content, isError) = await contents(
            fixture.tools(store), ToolCatalog.mediaGetName, ["message_id": .int(10)])
        #expect(isError)
        #expect(texts(content).contains("has no attachment file"))
    }

    @Test("A large photo comes back as a JPEG no longer than 1568 pixels on its long side")
    func photoIsReduced() async throws {
        let fixture = try MediaFixture()
        defer { fixture.remove() }
        let path = try fixture.file("big.png", try makePNG(width: 3200, height: 1600))
        let store = fixture.store([(10, Fixtures.attachment(.photo, path: path), nil)])

        let (content, isError) = await contents(
            fixture.tools(store), ToolCatalog.mediaViewName, ["message_id": .int(10)])
        #expect(!isError, Comment(rawValue: texts(content)))
        let image = try #require(images(content).first)
        #expect(image.mime == "image/jpeg")
        #expect(image.data.count <= 1_500_000)
        let source = try #require(CGImageSourceCreateWithData(image.data as CFData, nil))
        let properties = try #require(
            CGImageSourceCopyPropertiesAtIndex(source, 0, nil) as? [CFString: Any])
        let width = try #require(properties[kCGImagePropertyPixelWidth] as? Int)
        let height = try #require(properties[kCGImagePropertyPixelHeight] as? Int)
        #expect(max(width, height) <= MediaFiles.maximumImageSide)
        #expect(max(width, height) > 1000, "reduced far more than needed")
    }

    @Test("A file that is not an image is reported, not crashed on")
    func notAnImage() async throws {
        let fixture = try MediaFixture()
        defer { fixture.remove() }
        let path = try fixture.file("broken.jpg", Data("not an image".utf8))
        let store = fixture.store([(10, Fixtures.attachment(.photo, path: path), nil)])
        let (content, isError) = await contents(
            fixture.tools(store), ToolCatalog.mediaViewName, ["message_id": .int(10)])
        #expect(isError)
        #expect(texts(content).contains("could not be opened"))
    }

    @Test("A PDF returns its text; a scan says it has no text layer")
    func pdfText() async throws {
        let fixture = try MediaFixture()
        defer { fixture.remove() }
        let withText = try fixture.file("invoice.pdf", makePDF(text: "Invented invoice 42"))
        let scan = try fixture.file("scan.pdf", makePDF(text: nil))
        let store = fixture.store([
            (10, Fixtures.attachment(.document, path: withText), nil),
            (11, Fixtures.attachment(.document, path: scan), nil),
        ])

        let (first, firstError) = await contents(
            fixture.tools(store), ToolCatalog.mediaViewName, ["message_id": .int(10)])
        #expect(!firstError, Comment(rawValue: texts(first)))
        #expect(texts(first).contains("Invented invoice 42"))

        let (second, secondError) = await contents(
            fixture.tools(store), ToolCatalog.mediaViewName, ["message_id": .int(11)])
        #expect(!secondError)
        #expect(texts(second).contains("no text layer"))
    }

    @Test("A text document returns its text, cut at the limit with a note")
    func textDocument() async throws {
        let fixture = try MediaFixture()
        defer { fixture.remove() }
        let path = try fixture.file("notes.txt", Data("invented notes\n".utf8))
        let store = fixture.store([(10, Fixtures.attachment(.document, path: path), nil)])
        let (content, _) = await contents(
            fixture.tools(store), ToolCatalog.mediaViewName, ["message_id": .int(10)])
        #expect(texts(content).contains("invented notes"))

        let long = try MediaFiles.plainText(of: URL(fileURLWithPath: path), maxCharacters: 5)
        #expect(long.truncated)
        #expect(long.text == "inven")
    }

    @Test("A document of a kind this server cannot read says so and points to media_get")
    func unknownDocumentKind() async throws {
        let fixture = try MediaFixture()
        defer { fixture.remove() }
        let path = try fixture.file("sheet.xlsx", Data("PK".utf8))
        let store = fixture.store([(10, Fixtures.attachment(.document, path: path), nil)])
        let (content, isError) = await contents(
            fixture.tools(store), ToolCatalog.mediaViewName, ["message_id": .int(10)])
        #expect(!isError)
        #expect(texts(content).contains("No viewer for"))
    }

    @Test("A video comes back as the requested number of still frames")
    func videoFrames() async throws {
        let fixture = try MediaFixture()
        defer { fixture.remove() }
        let url = fixture.media.appendingPathComponent("clip.mp4")
        try await makeVideo(at: url)
        let store = fixture.store([(10, Fixtures.attachment(.video, path: url.path), nil)])

        let (content, isError) = await contents(
            fixture.tools(store), ToolCatalog.mediaViewName,
            ["message_id": .int(10), "frames": .int(3)])
        #expect(!isError, Comment(rawValue: texts(content)))
        #expect(images(content).count == 3)
        #expect(texts(content).contains("3 frames"))
    }

    @Test("A voice note is not played; the answer points to audio_transcribe")
    func audioIsNotPlayed() async throws {
        let fixture = try MediaFixture()
        defer { fixture.remove() }
        let path = try fixture.file("note.opus", Data([0, 1, 2]))
        let store = fixture.store([(10, Fixtures.attachment(.voiceNote, path: path, duration: 33), nil)])
        let (content, isError) = await contents(
            fixture.tools(store), ToolCatalog.mediaViewName, ["message_id": .int(10)])
        #expect(!isError)
        #expect(texts(content).contains("audio_transcribe"))
    }

    @Test("An image over the pixel limit is refused from its header, before any decoding")
    func imageOverPixelLimitIsRefused() throws {
        let fixture = try MediaFixture()
        defer { fixture.remove() }
        let path = try fixture.file("wide.png", try makePNG(width: 3200, height: 1600))
        #expect(
            throws: MediaFiles.ViewError.tooManyPixels(5_120_000, limit: 1_000_000)
        ) { _ = try MediaFiles.jpegData(of: URL(fileURLWithPath: path), maxPixels: 1_000_000) }
        // The shipped limit lets an ordinary photo through.
        _ = try MediaFiles.jpegData(of: URL(fileURLWithPath: path))
    }

    @Test("A header that claims an absurd size and carries no image is refused, not decoded")
    func bombHeaderIsRefused() throws {
        let fixture = try MediaFixture()
        defer { fixture.remove() }
        let path = try fixture.file("bomb.png", makeBombHeader(width: 60000, height: 60000))
        #expect(throws: MediaFiles.ViewError.self) {
            _ = try MediaFiles.jpegData(of: URL(fileURLWithPath: path))
        }
    }

    @Test("A long PDF stops extracting at the limit and says it was cut")
    func longPDFIsCutEarly() throws {
        let fixture = try MediaFixture()
        defer { fixture.remove() }
        let path = try fixture.file("long.pdf", makePDF(text: nil, pages: 40))
        let result = try MediaFiles.pdfText(of: URL(fileURLWithPath: path), maxCharacters: 30)
        #expect(result.pageCount == 40)
        #expect(result.truncated)
        #expect(result.text.count <= 30)
        #expect(result.text.contains("Page 1"))
        #expect(!result.text.contains("Page 40"))
    }

    @Test("Something that is not a regular file is refused instead of blocking on it")
    func specialFileIsRefused() throws {
        let fixture = try MediaFixture()
        defer { fixture.remove() }
        let fifo = fixture.media.appendingPathComponent("pipe.png")
        #expect(mkfifo(fifo.path, 0o600) == 0)
        #expect(throws: MediaFiles.ViewError.self) { _ = try MediaFiles.jpegData(of: fifo) }
        #expect(throws: MediaFiles.ViewError.self) { _ = try MediaFiles.facts(of: fifo) }
    }

    @Test("A video that cannot be decoded is an unreadable attachment, not a database error")
    func corruptVideoIsUnreadable() async throws {
        let fixture = try MediaFixture()
        defer { fixture.remove() }
        let path = try fixture.file("broken.mp4", Data(repeating: 7, count: 2048))
        let store = fixture.store([(10, Fixtures.attachment(.video, path: path), nil)])
        let (content, isError) = await contents(
            fixture.tools(store), ToolCatalog.mediaViewName, ["message_id": .int(10)])
        #expect(isError)
        #expect(texts(content).contains("could not be opened"))
        #expect(!texts(content).contains("database"))
    }

    @Test("A file deleted after the store reported it is absent, not an escape")
    func vanishedFileIsAbsent() async throws {
        let fixture = try MediaFixture()
        defer { fixture.remove() }
        let gone = fixture.media.appendingPathComponent("gone.png").path
        let store = fixture.store([(10, Fixtures.attachment(.photo, path: gone), nil)])
        let (content, isError) = await contents(
            fixture.tools(store), ToolCatalog.mediaGetName, ["message_id": .int(10)])
        #expect(!isError)
        #expect(texts(content).contains("not on this Mac"))
    }

    @Test("Paths that only look like Message/ are refused: its sibling, itself, and its parent")
    func lookalikePathsAreRefused() throws {
        let fixture = try MediaFixture()
        defer { fixture.remove() }
        let files = MediaFiles(root: fixture.root)
        let sibling = fixture.directory.appendingPathComponent("Message-evil")
        try FileManager.default.createDirectory(at: sibling, withIntermediateDirectories: true)
        try Data("x".utf8).write(to: sibling.appendingPathComponent("a.txt"))
        let inside = try fixture.file("ok.txt", Data("x".utf8))

        #expect(files.contained(sibling.appendingPathComponent("a.txt").path) == nil)
        #expect(files.contained(fixture.root.path) == nil)
        #expect(files.contained(fixture.directory.path) == nil)
        #expect(files.contained(inside) != nil)
        #expect(files.contained(fixture.media.path + "/../Media/ok.txt") != nil)
    }

    @Test("A file over the viewing limit is refused before it is read")
    func oversizedFileIsRefused() throws {
        let fixture = try MediaFixture()
        defer { fixture.remove() }
        let path = fixture.media.appendingPathComponent("huge.png")
        FileManager.default.createFile(atPath: path.path, contents: nil)
        let handle = try FileHandle(forWritingTo: path)
        try handle.truncate(atOffset: UInt64(MediaFiles.maximumDecodedFileBytes) + 1)  // sparse
        try handle.close()
        #expect(throws: MediaFiles.ViewError.self) { _ = try MediaFiles.jpegData(of: path) }
    }
}
